WebLink.url:
{!REQUIRESCRIPT("/soap/ajax/32.0/connection.js")}

try{

    var ContactToUpdate = new sforce.SObject("Contact");

    ContactToUpdate.Id = "{!Contact.Id}";
    ContactToUpdate.isSendEmailGDPR__c = true;
    ContactToUpdate.Data_invio_GDPR__c = null;
                ContactToUpdate.Data_risposta_GDPR__c = null;
                ContactToUpdate.privacy__c = null;
                ContactToUpdate.HasOptedOutOfEmail = false;

    var result = sforce.connection.update([ContactToUpdate]);

    if(result[0].success === "true"){
        location.reload();
    }
    else{
        alert("An Error has Occurred. Error: " + result[0].errors.message);
    }
}
catch(e){
    alert("An unexpected Error has Occurred. Error: " + e);
}
